export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const newTable = (headerDefined = false) => ({ t: 'table', m: new Map(), headerDefined })
const isWs = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

export function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  let currentPath = []
  for (let i = 0; i < lines.length; i++) {
    const p = new LineParser(lines[i], i + 1)
    const r = p.line(root, current, currentPath)
    if (r) {
      current = r.table
      currentPath = r.path
    }
  }
  return root
}

class LineParser {
  constructor(s, n) {
    this.s = s
    this.n = n
    this.i = 0
  }
  fail(msg) {
    throw new ParseError(this.n, msg)
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  atEnd() {
    // after whitespace: end of line or a comment
    return this.i >= this.s.length || isComment(this.s[this.i])
  }

  line(root, current, currentPath) {
    const s = this.s
    this.ws()
    if (this.i >= s.length || isComment(s[this.i])) return null
    if (s[this.i] === '[') return this.header(root)
    const names = this.dottedName()
    this.ws()
    if (s[this.i] !== '=') this.fail('expected key = value')
    this.i++
    const v = this.value()
    this.ws()
    if (!this.atEnd()) this.fail('trailing text after a value')
    this.assign(current, currentPath, names, v)
    return null
  }

  assign(table, prefix, names, v) {
    const { t, path } = this.walk(table, prefix, names.slice(0, -1))
    const last = names[names.length - 1]
    if (t.m.has(last)) this.fail(`key ${[...path, last].join('.')} is defined twice`)
    t.m.set(last, v)
  }

  walk(table, prefix, names) {
    let t = table
    const path = [...prefix]
    for (const name of names) {
      path.push(name)
      const e = t.m.get(name)
      if (!e) {
        const nt = newTable()
        t.m.set(name, nt)
        t = nt
      } else if (e.t === 'table') t = e
      else if (e.t === 'array' && e.aot) t = e.items[e.items.length - 1]
      else this.fail(`${path.join('.')} is not a table`)
    }
    return { t, path }
  }

  header(root) {
    const s = this.s
    const aot = s[this.i + 1] === '['
    this.i += aot ? 2 : 1
    this.ws()
    const names = this.dottedName()
    this.ws()
    const close = aot ? ']]' : ']'
    if (s.substr(this.i, close.length) !== close) this.fail('unterminated table header')
    this.i += close.length
    this.ws()
    if (!this.atEnd()) this.fail('trailing text after a table header')
    const { t, path } = this.walk(root, [], names.slice(0, -1))
    const last = names[names.length - 1]
    const full = [...path, last]
    const e = t.m.get(last)
    if (aot) {
      if (!e) {
        const nt = newTable(true)
        t.m.set(last, { t: 'array', aot: true, items: [nt] })
        return { table: nt, path: full }
      }
      if (e.t !== 'array' || !e.aot) this.fail(`${full.join('.')} is not an array of tables`)
