      e.items.push(nt)
      return { table: nt, path: full }
    }
    if (!e) {
      const nt = newTable(true)
      t.m.set(last, nt)
      return { table: nt, path: full }
    }
    if (e.t !== 'table') this.fail(`${full.join('.')} is not a table`)
    if (e.headerDefined) this.fail(`table ${full.join('.')} is defined twice`)
    e.headerDefined = true
    return { table: e, path: full }
  }

  name() {
    const s = this.s
    const c = s[this.i]
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (isBare(s[this.i])) this.i++
    if (this.i === st) this.fail('expected a name')
    return s.slice(st, this.i)
  }

  dottedName() {
    const names = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else {
        this.i = save
        return names
      }
    }
  }

  basicString() {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= s.length) this.fail('unterminated string')
      const c = s[this.i]
