        this.i++
        return out
      }
      if (c !== '\\') {
        out += c
        this.i++
        continue
      }
      this.i++
      if (this.i >= s.length) this.fail('unterminated string')
      const e = s[this.i]
      const cp = String.fromCodePoint(s.codePointAt(this.i))
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
