        this.i += 4
      } else this.fail(`invalid escape \\${cp}`)
      this.i += e === 'u' ? 1 : cp.length
    }
  }

  literalString() {
    const end = this.s.indexOf("'", this.i + 1)
    if (end < 0) this.fail('unterminated string')
    const out = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return out
  }

  value() {
    const s = this.s
    this.ws()
    const c = s[this.i]
    if (c === undefined || c === ',' || c === ']' || c === '}' || isComment(c)) this.fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basicString() }
    if (c === "'") return { t: 'string', v: this.literalString() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (this.i < s.length && !isWs(s[this.i]) && !',]}'.includes(s[this.i])) this.i++
    const w = s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
