      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    this.fail(`invalid value ${w}`)
  }

  array() {
    const s = this.s
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (s[this.i] === ']') {
        this.i++
        return { t: 'array', aot: false, items }
      }
      items.push(this.value())
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (s[this.i] === ',') this.i++
      else if (s[this.i] !== ']') this.fail('trailing text after a value')
    }
  }

  inline() {
    const s = this.s
    this.i++
    const table = newTable()
    this.ws()
    if (s[this.i] === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.dottedName()
      this.ws()
      if (s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      const v = this.value()
      this.assign(table, [], names, v)
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (s[this.i] === ',') this.i++
      else if (s[this.i] === '}') {
        this.i++
        return table
      } else this.fail('trailing text after a value')
    }
  }
}
