    if (end < 0) this.fail('unterminated string')
    const out = this.s.slice(this.i + 1, end)
    this.i = end + 1
    return out
  }

  value() {
    const s = this.s
    this.ws()
    const c = s[this.i]
    if (c === undefined || c === ',' || c === ']' || c === '}' || isComment(c)) this.fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basicString() }
    if (c === "'") return { t: 'string', v: this.literalString() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (this.i < s.length && !isWs(s[this.i]) && !',]}'.includes(s[this.i])) this.i++
    const w = s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    const int = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp(`^${int}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^${int}(?:\\.\\d+(?:_\\d+)*)?(?:[eE][+-]?\\d+(?:_\\d+)*)?$`).test(w)) {
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    }
    this.fail(`invalid value ${w}`)
  }

  array() {
    const s = this.s
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (s[this.i] === ']') {
        this.i++
        return { t: 'array', aot: false, items }
      }
      items.push(this.value())
      this.ws()
      if (this.atEnd()) this.fail('unterminated array')
      if (s[this.i] === ',') this.i++
      else if (s[this.i] !== ']') this.fail('trailing text after a value')
    }
  }

  inline() {
    const s = this.s
    this.i++
    const table = newTable()
    this.ws()
    if (s[this.i] === '}') {
      this.i++
      return table
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      const names = this.dottedName()
      this.ws()
      if (s[this.i] !== '=') this.fail('expected = in an inline table')
      this.i++
      const v = this.value()
      this.assign(table, [], names, v)
      this.ws()
      if (this.atEnd()) this.fail('unterminated inline table')
      if (s[this.i] === ',') this.i++
      else if (s[this.i] === '}') {
        this.i++
        return table
      } else this.fail('trailing text after a value')
    }
  }
}
