const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function json(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return `{\n${ks.map((k) => `${pad}${JSON.stringify(k)}: ${json(n.m.get(k), ind + 1)}`).join(',\n')}\n${end}}`
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return `[\n${n.items.map((x) => pad + json(x, ind + 1)).join(',\n')}\n${end}]`
  }
  return JSON.stringify(n.v)
}

export const toJson = (root) => json(root, 0) + '\n'

export function toKeys(root) {
  const out = []
  const walk = (n, path) => {
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${n.m.get(k).t}`)
        walk(n.m.get(k), p)
      }
    } else if (n.t === 'array') {
      n.items.forEach((x, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${x.t}`)
        walk(x, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
